  ('Pescado a la plancha con yuca cocida', 'cena', 'musculo,resistencia,grasa', 450, 34, 30, 'Proteína limpia y un carbohidrato de la región.', '["1 filete de pescado (130 g)","1 trozo de yuca (100 g)","Limón","Ensalada verde"]'::jsonb, '["Cocina la yuca en agua con sal hasta que ablande.","Haz el pescado a la plancha con limón.","Sirve con la ensalada."]'::jsonb),
  ('Ensalada de garbanzos', 'cena', 'grasa,movilidad', 400, 17, 10, 'Fría, fresca y con mucha fibra.', '["1 taza de garbanzos cocidos","Tomate, pepino y cebolla morada","Perejil","Limón y aceite de oliva"]'::jsonb, '["Pica las verduras.","Mezcla con los garbanzos.","Aliña con limón, una cucharadita de aceite y sal."]'::jsonb),
  ('Fruta picada con limón', 'snack', 'grasa,resistencia,movilidad', 140, 2, 5, 'Mango, piña o papaya de temporada.', '["1 taza de fruta picada","Zumo de limón"]'::jsonb, '["Pica la fruta y agrega el limón."]'::jsonb),
  ('Yogur natural con frutos secos', 'snack', 'musculo,resistencia,grasa', 250, 12, 2, 'Proteína y grasas buenas entre comidas.', '["1 vaso de yogur natural","1 puñado pequeño de maní o almendras"]'::jsonb, '["Sirve el yogur y agrega los frutos secos."]'::jsonb),
  ('Chontaduro con sal', 'snack', 'musculo,resistencia', 210, 3, 2, 'Energía del Pacífico, mejor sin miel.', '["3 chontaduros cocidos","Sal al gusto"]'::jsonb, '["Pela y sirve con una pizca de sal."]'::jsonb),
