  ('Batido de borojó (porción pequeña)', 'snack', 'musculo,resistencia', 200, 8, 5, 'Ideal después de entrenar.', '["1/4 taza de pulpa de borojó","1 vaso de leche","Hielo"]'::jsonb, '["Licúa y toma después de la sesión."]'::jsonb);
insert into public.consejos (categoria, texto) values
  ('hidratacion', 'Mantente hidratado. Con el calor del Pacífico tu cuerpo pierde más agua de la que crees.'),
  ('hidratacion', 'Ten una botella a la vista mientras entrenas: si la ves, la tomas.'),
  ('proteina', 'Incluye una fuente de proteína en cada comida: huevo, pescado, pollo, lentejas o yogur.'),
  ('proteina', 'El pescado de la región es de las proteínas más limpias y económicas que tienes cerca.'),
  ('porciones', 'Mitad del plato verduras, un cuarto proteína y un cuarto carbohidrato. Es la regla más simple que funciona.'),
  ('porciones', 'Cocina el plátano cocido o al horno en vez de frito: misma comida, mucha menos grasa.'),
  ('descanso', 'Dormir 7 a 8 horas también es entrenar: ahí es donde el músculo se recupera.'),
  ('descanso', 'Un día de descanso activo (caminar, estirar) ayuda más que no moverse nada.'),
  ('habitos', 'No busques perfección: si una comida no salió como querías, la siguiente es una nueva oportunidad.'),
  ('habitos', 'Prepara la proteína del día desde la mañana y evitarás comer lo primero que encuentres.'),
  ('azucar', 'Los jugos con azúcar suman calorías rápido. Prueba la fruta entera o el agua con limón.'),
  ('entreno', 'Come algo ligero 1 a 2 horas antes de entrenar: fruta, avena o una arepa pequeña.'),
  ('entreno', 'Después de entrenar, combina proteína y carbohidrato: por ejemplo, batido de borojó o huevo con fruta.');
